    (void)(m_assertEqual(Args{pvz::getattr(pvz::getattr(L_host, SY("campaign")), SY("deck")), rd(rd(pvz::getattr(pvz::getattr(pvz::getattr(L_host, SY("room")), SY("battle")), SY("players")), SV("plant")), SV("deck"))}));
