    (void)(m_tcp_until(Args{L_host, L_guest, V::func([=, this](const Args& A) -> V { return py_and(V((pvz::getattr(pvz::getattr(L_host, SY("room")), SY("phase")) == SV("battle"))), [&]() -> V { return V((py::m_get(pvz::getattr(L_guest, SY("view")), SV("phase")) == SV("battle"))); }); })}));
